<!doctype html><html lang="es"><head><meta charset="utf-8"><title>Reporte {{ $from }} - {{ $to }}</title><style>body{font-family:Arial;color:#222;padding:28px}h1{color:#be185d}table{width:100%;border-collapse:collapse}th,td{border:1px solid #ddd;padding:8px;text-align:left}th{background:#fce7f3}.actions{margin-bottom:20px}@media print{.actions{display:none}}</style></head><body><div class="actions"><button onclick="window.print()">Imprimir / Guardar como PDF</button></div><h1>Reporte e informe</h1><p>Período: {{ $from }} al {{ $to }}</p><table><thead><tr><th>Fecha</th><th>Tipo</th><th>Documento</th><th>Tercero</th><th>Total</th></tr></thead><tbody>@foreach($rows as $row)<tr><td>{{ $row['date'] }}</td><td>{{ $row['type'] }}</td><td>{{ $row['document'] }}</td><td>{{ $row['third_party'] }}</td><td>${{ number_format($row['total'], 2) }}</td></tr>@endforeach</tbody></table><script>window.addEventListener('load',()=>window.print())</script></body></html>
